import os
import requests
import re
from html.parser import HTMLParser

class PGParser(HTMLParser):
    def __init__(self):
        super().__init__()
        self.text = []
        self.in_script = False
        self.in_style = False

    def handle_starttag(self, tag, attrs):
        if tag == "script":
            self.in_script = True
        elif tag == "style":
            self.in_style = True
        elif tag == "br":
            self.text.append("\n")

    def handle_endtag(self, tag):
        if tag == "script":
            self.in_script = False
        elif tag == "style":
            self.in_style = False

    def handle_data(self, data):
        if not self.in_script and not self.in_style:
            self.text.append(data)

    def get_text(self):
        full_text = "".join(self.text)
        # Basic cleaning
        full_text = re.sub(r'\n\s*\n', '\n\n', full_text)
        return full_text.strip()

def fetch_essay(url):
    response = requests.get(url)
    response.raise_for_status()
    parser = PGParser()
    parser.feed(response.text)
    return parser.get_text()

def clean_pg_text(text, title):
    # Paul Graham's essays usually have a side menu that gets included.
    # We try to find the start of the essay.
    # Often it starts with a date like "July 2013" or "September 2024"
    # Or we can just try to find the title.

    # Actually, simpler: looking at the HTML, the main content is in the third <td> or so.
    # But since we just want the text, we can look for common patterns.

    # For "Do Things that don't scale", it starts after "bio" or something.
    # Let's just keep the whole thing and hope the TTS handles it, or do some manual trimming.

    # Manual trimming for PG essays:
    if "index.htmlarticles.html" in text:
        text = text.split("mas.to/@paulg")[-1]

    # Remove "Notes" at the end
    if "Notes\n" in text:
        text = text.split("Notes\n")[0]

    return title + "\n\n" + text.strip()

def chunk_text(text, limit=4000):
    chunks = []
    while len(text) > limit:
        # Find last space within limit
        idx = text.rfind(" ", 0, limit)
        if idx == -1:
            idx = limit
        chunks.append(text[:idx])
        text = text[idx:].strip()
    chunks.append(text)
    return chunks

def main():
    api_key = os.environ.get("OPENAI_API_KEY")
    if not api_key:
        print("Error: OPENAI_API_KEY not found.")
        return

    essays = [
        ("Do Things that Don't Scale", "http://paulgraham.com/ds.html"),
        ("Founder Mode", "http://paulgraham.com/foundermode.html")
    ]

    combined_text = ""
    for title, url in essays:
        print(f"Fetching {title}...")
        raw_text = fetch_essay(url)
        cleaned_text = clean_pg_text(raw_text, title)
        combined_text += cleaned_text + "\n\n" + "---" + "\n\n"

    chunks = chunk_text(combined_text)
    print(f"Total chunks: {len(chunks)}")

    temp_files = []
    for i, chunk in enumerate(chunks):
        print(f"Processing chunk {i+1}/{len(chunks)}...")
        response = requests.post(
            "https://api.openai.com/v1/audio/speech",
            headers={"Authorization": f"Bearer {api_key}"},
            json={
                "model": "tts-1",
                "voice": "alloy",
                "input": chunk
            }
        )
        response.raise_for_status()
        temp_file = f"chunk_{i}.mp3"
        with open(temp_file, "wb") as f:
            f.write(response.content)
        temp_files.append(temp_file)

    # Use ffmpeg to concatenate
    with open("list.txt", "w") as f:
        for temp_file in temp_files:
            f.write(f"file '{temp_file}'\n")

    print("Concatenating audio files...")
    os.system("ffmpeg -y -f concat -safe 0 -i list.txt -c copy /root/audiobook.mp3")

    # Cleanup
    for temp_file in temp_files:
        os.remove(temp_file)
    os.remove("list.txt")
    print("Done! Audiobook saved to /root/audiobook.mp3")

if __name__ == "__main__":
    main()

